_SPLIT = 144
_BLOCKABLE = ("PLANT", "BUILD_COOP", "BUILD_PASTURE")
_S = {"delay": defaultdict(int), "day": -1, "arm": None}


def agent(observation, configuration=None):
    obs = observation
    step = obs.get("step", 0)
    seat = int(obs.get("player", 0))
    day = step // 24
    if step == 0:
        _S["arm"] = None
        _S["delay"].clear()
    if _S["arm"] is None and step >= _SPLIT:
        shops = (obs.get("town") or {}).get("unlocked_shops") or []
        _S["arm"] = "yarn" if "YARN_STORE" in shops[:2] else "noyarn"
    tape = _TAPES[_S["arm"] or "noyarn"]
    if day != _S["day"]:
        _S["delay"].clear()
        _S["day"] = day
    me = obs["farms"][seat]
    units = [me.get("farmer")] + list(me.get("hands") or [])
    tiles = me.get("tiles") or []
    base = tape[step] if 0 <= step < len(tape) else {}
    out = {"farmer": ["PASS"], "hands": [], "market": list(base.get("market") or [])}
    for i, unit in enumerate(units):
        t = step - _S["delay"][i]
        src = tape[t] if 0 <= t < len(tape) else {}
        seq = [src.get("farmer") or ["PASS"]] + list(src.get("hands") or [])
        a = seq[i] if i < len(seq) else ["PASS"]
        if not isinstance(a, list) or not a:
            a = ["PASS"]
        if a[0] in _BLOCKABLE and isinstance(unit, (list, tuple)) and len(unit) >= 2:
            try:
                tile = tiles[unit[1]][unit[0]]
            except Exception:
                tile = None
            if isinstance(tile, dict) and tile.get("kind") == "WEED":
                a = ["DIG"]
                _S["delay"][i] += 1
        if i == 0:
            out["farmer"] = a
        else:
            out["hands"].append(a)
    return out
